#!/usr/bin/env python3
"""Patch the freshly scaffolded Android project.

The android/ folder is generated by `flutter create` on the CI runner, so this
script adds what the app needs on top of the default template:

  * INTERNET + RECORD_AUDIO (+ bluetooth) permissions
  * <queries> entries so speech recognition and TTS are visible on Android 11+
  * a friendly app label
  * minSdkVersion 23
  * the app's own launcher icons

It is written to be idempotent and to fail loudly if the expected files are
missing.
"""

import pathlib
import re
import shutil
import sys

MANIFEST = pathlib.Path("android/app/src/main/AndroidManifest.xml")
GRADLE = pathlib.Path("android/app/build.gradle")
RES_DIR = pathlib.Path("android/app/src/main/res")
ICON_SOURCE = pathlib.Path("assets/icon")

PERMISSIONS = """
    <!-- Added for LinguaCoach AI: network access for Gemini + microphone for
         live voice classes and speech recognition. -->
    <uses-permission android:name="android.permission.INTERNET"/>
    <uses-permission android:name="android.permission.RECORD_AUDIO"/>
    <uses-permission android:name="android.permission.MODIFY_AUDIO_SETTINGS"/>
    <uses-permission android:name="android.permission.BLUETOOTH"/>
    <uses-permission android:name="android.permission.BLUETOOTH_ADMIN"/>
"""

QUERY_INTENTS = """
        <!-- Speech recognition (speech_to_text) -->
        <intent>
            <action android:name="android.speech.RecognitionService" />
        </intent>
        <!-- Text to speech (flutter_tts) -->
        <intent>
            <action android:name="android.intent.action.TTS_SERVICE" />
        </intent>"""


def patch_manifest() -> None:
    if not MANIFEST.exists():
        sys.exit(f"ERROR: {MANIFEST} not found")

    text = MANIFEST.read_text(encoding="utf-8")

    if "android.permission.RECORD_AUDIO" not in text:
        text = re.sub(r"(<manifest[^>]*>)", r"\1\n" + PERMISSIONS, text, count=1)

    # A friendlier name than the package id.
    text = re.sub(
        r'android:label="[^"]*"', 'android:label="LinguaCoach AI"', text, count=1
    )

    if "android.speech.RecognitionService" not in text:
        if "<queries>" in text:
            text = text.replace("<queries>", "<queries>" + QUERY_INTENTS, 1)
        else:
            text = text.replace(
                "</manifest>",
                "    <queries>" + QUERY_INTENTS + "\n    </queries>\n</manifest>",
                1,
            )

    MANIFEST.write_text(text, encoding="utf-8")
    print("Patched", MANIFEST)


def patch_gradle() -> None:
    if not GRADLE.exists():
        sys.exit(f"ERROR: {GRADLE} not found")

    original = GRADLE.read_text(encoding="utf-8")
    text = original

    # record_android (used for the live-class microphone) requires API 23.
    # Flutter templates use either `minSdk = flutter.minSdkVersion` (newer) or
    # `minSdkVersion flutter.minSdkVersion` (older), so cover both.
    text = re.sub(r"minSdk\s*=\s*flutter\.minSdkVersion", "minSdk = 23", text)
    text = re.sub(
        r"minSdkVersion\s+flutter\.minSdkVersion", "minSdkVersion 23", text
    )
    text = re.sub(r"minSdkVersion\s+21\b", "minSdkVersion 23", text)
    text = re.sub(r"minSdk\s*=\s*21\b", "minSdk = 23", text)

    GRADLE.write_text(text, encoding="utf-8")

    # Echo the result so a mismatch is obvious in the CI log.
    print("--- minSdk lines in build.gradle ---")
    for line in text.splitlines():
        if "minSdk" in line:
            print("   ", line.strip())
    if text == original:
        print("WARNING: no minSdk line was changed; check the template syntax.")
    else:
        print("Patched", GRADLE)


def patch_icons() -> None:
    """Copy the app's launcher icons over the Flutter default ones."""
    if not ICON_SOURCE.exists():
        print("No icon assets found; keeping the default launcher icon.")
        return
    if not RES_DIR.exists():
        sys.exit(f"ERROR: {RES_DIR} not found")

    copied = 0
    for density_dir in sorted(ICON_SOURCE.glob("mipmap-*")):
        icon = density_dir / "ic_launcher.png"
        if not icon.exists():
            continue
        target_dir = RES_DIR / density_dir.name
        target_dir.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(icon, target_dir / "ic_launcher.png")
        copied += 1

    # Round icon, if the template references one.
    base = ICON_SOURCE / "mipmap-xxxhdpi" / "ic_launcher.png"
    if base.exists():
        for density_dir in sorted(RES_DIR.glob("mipmap-*")):
            rounded = density_dir / "ic_launcher_round.png"
            if rounded.exists():
                shutil.copyfile(
                    ICON_SOURCE / density_dir.name / "ic_launcher.png", rounded
                )
                copied += 1

    print(f"Replaced {copied} launcher icon file(s).")


if __name__ == "__main__":
    patch_manifest()
    patch_gradle()
    patch_icons()
    print("Android project patched successfully.")
